# simpler: occurrences of 'Demo pair N input' followed eventually by digit runs of same width >=4, stop at next header word
occurrences=[m.start() for m in re.finditer(f'Demo pair {n} input',t)]
seen=set()
for p in occurrences:
    k='Demo pair %d input'%n
    if p in seen: continue
    seg=t[p+1:].split('\n')
    rows=[]
    widths={}
    ok=True
    for ln in seg:
        s=ln.rstrip(); 
        if not s: continue
        if s.isdigit(): 
            rows.append(s); widths[len(s)]=widths.get(len(s),0)+1
            if len(rows)>80: ok=False;break
        elif ':' in s and 'x' in s.lower():
            break
